CREATE TABLE operation_settings (workspace_id text NOT NULL, environment text NOT NULL CHECK (environment IN ('live','test')), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(workspace_id,environment));
CREATE TABLE operation_domains (id text PRIMARY KEY, workspace_id text NOT NULL, environment text NOT NULL CHECK (environment IN ('live','test')), name text NOT NULL, region text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX operation_domain_scope ON operation_domains(workspace_id,environment,name,region);
CREATE TABLE operation_webhooks (id text PRIMARY KEY, workspace_id text NOT NULL, environment text NOT NULL CHECK (environment IN ('live','test')), url text NOT NULL, description text NOT NULL DEFAULT '', event_types jsonb NOT NULL, regions jsonb, paused boolean NOT NULL DEFAULT false, encrypted_secret text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX operation_webhook_scope ON operation_webhooks(workspace_id,environment,id);
CREATE TABLE operation_events (id text NOT NULL, workspace_id text NOT NULL, environment text NOT NULL CHECK (environment IN ('live','test')), type text NOT NULL, region text, data jsonb NOT NULL, created_at timestamptz NOT NULL, PRIMARY KEY(workspace_id,environment,id));
CREATE INDEX operation_events_metrics ON operation_events(workspace_id,environment,created_at);
CREATE TABLE operation_deliveries (id text PRIMARY KEY, workspace_id text NOT NULL, environment text NOT NULL CHECK (environment IN ('live','test')), webhook_id text NOT NULL, event_id text NOT NULL, payload jsonb NOT NULL, synthetic boolean NOT NULL DEFAULT false, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','delivered','failed','paused')), attempt_count integer NOT NULL DEFAULT 0, generation integer NOT NULL DEFAULT 0, last_status_code integer, last_error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX operation_delivery_scope ON operation_deliveries(workspace_id,environment,webhook_id,id);
CREATE UNIQUE INDEX operation_delivery_event ON operation_deliveries(workspace_id,environment,webhook_id,event_id);
CREATE TABLE operation_delivery_attempts (id text PRIMARY KEY, workspace_id text NOT NULL, environment text NOT NULL CHECK (environment IN ('live','test')), delivery_id text NOT NULL, status_code integer, error text, duration_ms integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX operation_attempt_delivery ON operation_delivery_attempts(workspace_id,environment,delivery_id);
CREATE TABLE operation_sns_receipts (topic_arn text NOT NULL, message_id text NOT NULL, workspace_id text NOT NULL, environment text NOT NULL CHECK (environment IN ('live','test')), processed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(topic_arn,message_id));
CREATE TABLE operation_unsubscribe_tokens (token_hash text PRIMARY KEY, workspace_id text NOT NULL, environment text NOT NULL CHECK (environment IN ('live','test')), email text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
